<script setup>
import {sitePath} from '../paths.js';

import {ref,computed,onMounted,onBeforeUnmount,nextTick,watch} from 'vue';
import {ArrowLeft,ArrowUpRight,ArrowDownToLine,Check,ChevronDown,ChevronRight,MousePointer2,PenLine,Spline,Undo2,Redo2,Play,Pause,Grid2X2,Magnet,ScanLine,Expand,Plus,Minus,Layers,Image,Type,SlidersHorizontal,Eye,EyeOff,Copy,Trash2,X,Upload,Code2,FileJson,Download,CheckCheck,MoveHorizontal,Command,Info,Keyboard,Focus,PanelTop,ExternalLink,Maximize2,RotateCcw,Search} from 'lucide-vue-next';
import EffectSwatch from './EffectSwatch.vue';import {lineEffects,tailEffects,lineRadius} from './lineEffects';
import {trimLinePaths} from './pathTrimming';
import HeaderRenderer from './HeaderRenderer.vue';import StudioRange from './StudioRange.vue';
import {presets,makeConfig,validateConfig} from './presets';import {pathData,mirrored,WIDTH} from './geometry';import {useStudio} from './useStudio';import {buildPackage,standaloneSource,componentSource,downloadBlob} from './export';import './studio.css';
const {config,selectedId,selected,tool,playing,snap,showGrid,showGuides,mirrorDraw,canUndo,canRedo,saveState,toast,message,record,undo,redo,choosePreset,remove,duplicate}=useStudio();
const effectCategory=ref('全部');
const availableEffects=computed(()=>lineEffects.filter(e=>effectCategory.value==='全部'||e.family===effectCategory.value));
const selectedEffect=computed(()=>lineEffects.find(e=>e.id===selected.value?.effect));
function chooseEffect(e){if(!selected.value)return;Object.assign(selected.value,{effect:e.id,width:e.width,duration:e.duration,tail:e.tail,glow:e.glow});record();}
const sidebar=ref('presets'),query=ref(''),category=ref('全部'),preview=ref(false),codeOpen=ref(false),exportMenu=ref(false),shortcutsOpen=ref(false),exporting=ref(false),codeTab=ref('vue'),copied=ref(false),draft=ref([]),hoverPoint=ref(null),pointer=ref(null),stage=ref(null),fileInput=ref(null),jsonInput=ref(null),zoom=ref(1),referenceMode=ref('header'),previewWidth=ref(1600),uploadBusy=ref(false);let dragging=null,wasPlaying=true,lastFocus=null;
watch([preview,codeOpen,shortcutsOpen],async ([a,b,c])=>{if(a||b||c){lastFocus=document.activeElement;await nextTick();const dialog=document.querySelector('.studio-modal-backdrop [role=dialog]');dialog?.querySelector('button,select')?.focus();}else lastFocus?.focus?.()});
const filtered=computed(()=>presets.filter(p=>(category.value==='全部'||(category.value==='新作'?p.fresh:p.tag.startsWith(category.value)))&&(p.name+p.en+p.tag).toLowerCase().includes(query.value.toLowerCase())));
const activePreset=computed(()=>presets.find(p=>p.id===config.value.presetId));
const draftD=computed(()=>pathData([...draft.value,...(hoverPoint.value?[hoverPoint.value]:[])],tool.value==='curve'?'curve':'line'));
const code=computed(()=>codeTab.value==='json'?JSON.stringify(config.value,null,2):componentSource(config.value));
const resolvedPaths=computed(()=>trimLinePaths(config.value.lines,lineRadius));
const selectedPaths=computed(()=>resolvedPaths.value.find(l=>l.line.id===selectedId.value)?.paths||[]);
const trimmedCount=computed(()=>resolvedPaths.value.reduce((count,l)=>count+l.paths.filter(p=>p.trimmed).length,0));
const pointCount=computed(()=>config.value.lines.reduce((a,l)=>a+l.points.length,0));

function applyPreset(p){choosePreset(p);if(p.fresh){showGrid.value=false;showGuides.value=false;}}
function setTool(t){draft.value=[];hoverPoint.value=null;tool.value=t;}
function point(e){const r=stage.value.getBoundingClientRect(),p={x:(e.clientX-r.left)/r.width*WIDTH,y:(e.clientY-r.top)/r.height*config.value.height};if(snap.value){p.x=Math.round(p.x/10)*10;p.y=Math.round(p.y/10)*10}p.x=Math.max(0,Math.min(1600,p.x));p.y=Math.max(0,Math.min(config.value.height,p.y));return p;}
function canvasDown(e){if(e.button!==0)return;if(tool.value==='select'){selectedId.value=null;return}const p=point(e);if(e.shiftKey&&draft.value.length){const last=draft.value.at(-1);if(Math.abs(p.x-last.x)>Math.abs(p.y-last.y))p.y=last.y;else p.x=last.x;}if(e.detail===2)return;draft.value.push(p);hoverPoint.value=p;}
function move(e){pointer.value=point(e);if(dragging){const p=pointer.value;if(dragging.kind==='node'){const l=config.value.lines.find(l=>l.id===dragging.id);if(l)l.points[dragging.index]={x:dragging.mirrored?1600-p.x:p.x,y:p.y}}else{config.value.titleX=Math.max(0,Math.min(1600,p.x-dragging.offsetX));config.value.titleY=Math.max(0,Math.min(config.value.height,p.y-dragging.offsetY));}return;}if(draft.value.length)hoverPoint.value=pointer.value;}
function startNode(e,index,isMirror=false){if(tool.value!=='select')return;e.preventDefault();dragging={kind:'node',id:selectedId.value,index,mirrored:isMirror};stage.value.setPointerCapture(e.pointerId);e.stopPropagation();}
function startTitle(e){if(tool.value!=='select')return;e.preventDefault();selectedId.value='title';const p=point(e);dragging={kind:'title',offsetX:p.x-config.value.titleX,offsetY:p.y-config.value.titleY};stage.value.setPointerCapture(e.pointerId);e.stopPropagation();}
function endDrag(e){if(dragging){dragging=null;record();if(stage.value?.hasPointerCapture(e.pointerId))stage.value.releasePointerCapture(e.pointerId)}}
function finish(){if(draft.value.length<2){if(draft.value.length)message('再添加一个节点即可完成线条');return;}const id='line-'+crypto.randomUUID();config.value.lines.push({id,name:'自定义光轨 '+(config.value.lines.length+1),points:draft.value.map(p=>({...p})),kind:tool.value==='curve'?'curve':'line',color:config.value.accent,width:1.8,duration:5.5,tail:100,glow:5,opacity:1,mirror:mirrorDraw.value,visible:true,effect:'comet',direction:'forward'});selectedId.value=id;draft.value=[];hoverPoint.value=null;tool.value='select';record();message('光轨已完成，交点已自动裁剪');}
function selectLine(id){if(tool.value!=='select')return;selectedId.value=id;showGuides.value=true;}
function toggleVisible(l){l.visible=!l.visible;record()}
function deleteNode(index){if(!selected.value)return;if(selected.value.points.length<=2){message('一条光轨至少需要两个节点');return}selected.value.points.splice(index,1);record()}
function addNode(){if(!selected.value)return;const p=selected.value.points,mid=Math.floor((p.length-1)/2),a=p[mid],b=p[mid+1];p.splice(mid+1,0,{x:Math.round((a.x+b.x)/2),y:Math.round((a.y+b.y)/2)});record();message('已在中间增加节点，可拖动调整')}
function undoAction(){if(draft.value.length){draft.value.pop();return}undo()}
function keydown(e){if(e.key==='Tab'&&(preview.value||codeOpen.value||shortcutsOpen.value)){const dialog=document.querySelector('.studio-modal-backdrop [role=dialog]'),items=[...(dialog?.querySelectorAll('button:not([disabled]),select,input,textarea,pre[tabindex]')||[])];const first=items[0],last=items.at(-1);if(e.shiftKey&&(document.activeElement===first||!dialog?.contains(document.activeElement))){e.preventDefault();last?.focus()}else if(!e.shiftKey&&(document.activeElement===last||!dialog?.contains(document.activeElement))){e.preventDefault();first?.focus()}return;}const editing=/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)||e.target.isContentEditable;if(e.key==='Escape'){if(codeOpen.value)codeOpen.value=false;else if(preview.value)closePreview();else if(shortcutsOpen.value)shortcutsOpen.value=false;else if(draft.value.length)setTool('select');else exportMenu.value=false;return}if(editing)return;if(codeOpen.value||preview.value||shortcutsOpen.value)return;if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?redo():undoAction();return}if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='d'){e.preventDefault();duplicate();return}if(e.key==='Enter'){e.preventDefault();finish()}else if(e.key==='Delete'||e.key==='Backspace'){e.preventDefault();if(draft.value.length)draft.value.pop();else remove()}else if(e.code==='Space'){e.preventDefault();playing.value=!playing.value}else if(e.key.toLowerCase()==='v')setTool('select');else if(e.key.toLowerCase()==='p')setTool('line');else if(e.key.toLowerCase()==='b')setTool('curve');else if(e.key.toLowerCase()==='g')showGrid.value=!showGrid.value;}
function onOutside(e){if(!e.target.closest('.export-group'))exportMenu.value=false}
onMounted(()=>{document.addEventListener('keydown',keydown);document.addEventListener('pointerdown',onOutside)});onBeforeUnmount(()=>{document.body.style.overflow='';document.removeEventListener('keydown',keydown);document.removeEventListener('pointerdown',onOutside)});
function openPreview(){preview.value=true;wasPlaying=playing.value;playing.value=true;document.body.style.overflow='hidden'}function closePreview(){preview.value=false;playing.value=wasPlaying;document.body.style.overflow=''}
function jsonDownload(){downloadBlob(new Blob([JSON.stringify(config.value,null,2)],{type:'application/json'}),'header.config.json');exportMenu.value=false;message('可编辑配置已下载')}
async function exportFile(kind='zip'){if(exporting.value)return;exporting.value=true;exportMenu.value=false;try{if(kind==='vue'){const text=await standaloneSource(config.value);downloadBlob(new Blob([text],{type:'text/plain;charset=utf-8'}),'DashboardHeader.vue')}else downloadBlob(await buildPackage(config.value),'header-studio-component.zip');message(kind==='vue'?'Vue 组件已下载，背景已内嵌':'组件包已下载，包含背景、配置和使用说明')}catch(e){message(e.message||'导出失败，请重试')}finally{exporting.value=false}}
async function copyCode(){try{await navigator.clipboard.writeText(code.value);copied.value=true;setTimeout(()=>copied.value=false,2000)}catch{message('无法访问剪贴板，请选择代码后复制')}}
async function uploadBackground(e){const file=e.target.files?.[0];e.target.value='';if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)){message('请选择 PNG、JPG 或 WebP 图片');return}if(file.size>3*1024*1024){message('请选择 3 MB 以内的图片，以便自动保存草稿');return}uploadBusy.value=true;try{const url=await new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(r.result);r.onerror=rej;r.readAsDataURL(file)});const size=await new Promise((res,rej)=>{const i=new window.Image();i.onload=()=>res({width:i.naturalWidth,height:i.naturalHeight});i.onerror=rej;i.src=url});const cropH=Math.min(size.height,size.width*config.value.height/1600);config.value.background={url,...size,crop:{x:0,y:(size.height-cropH)/2,w:size.width,h:cropH},opacity:1};config.value.presetId='custom';record();message('背景已导入，可在画布参数中调整裁切')}catch{message('图片读取失败，请更换图片')}finally{uploadBusy.value=false}}
async function importJson(e){const f=e.target.files?.[0];e.target.value='';if(!f)return;if(f.size>6*1024*1024){message('配置文件过大，请选择 6 MB 以内的 JSON');return}try{config.value=validateConfig(JSON.parse(await f.text()));selectedId.value=config.value.lines[0]?.id||'title';record();message('配置已恢复，可继续编辑')}catch(err){message(err.message||'配置导入失败')}}
function duplicateSelected(){duplicate();message('光轨已复制')}
function focusTitle(){selectedId.value='title';setTool('select')}
function resetBackground(){const p=activePreset.value;if(p){config.value.background=makeConfig(p).background;record();message('背景裁切已恢复')}}
</script>
<template><div class="header-studio">
 <header class="studio-topbar"><a class="studio-logo" :href="sitePath('/header-studio/')" aria-label="Header Studio 首页"><span><PanelTop :size="20" :stroke-width="1.7"/></span><strong>Header<span>Studio</span><i>BETA</i></strong></a><div class="studio-breadcrumb"><a :href="sitePath('/')">大屏工作空间</a><ChevronRight :size="12"/><span>Header 设计器</span></div><div class="studio-top-actions"><span class="studio-save"><i></i>{{saveState}}</span><button class="studio-btn secondary" @click="openPreview"><Eye :size="15"/>预览</button><div class="export-group"><button class="studio-btn primary" :disabled="exporting" @click="exportFile()"><Download :size="15"/>{{exporting?'正在打包…':'导出组件'}}</button><button class="studio-export-more" :aria-expanded="exportMenu" aria-label="更多导出方式" @click="exportMenu=!exportMenu"><ChevronDown :size="14"/></button><div v-if="exportMenu" class="studio-export-menu"><span>导出你的设计</span><button @click="exportFile()"><Layers :size="15"/><div>完整组件包 <small>.zip · 组件 + 背景 + 配置</small></div></button><button @click="exportFile('vue')"><Code2 :size="15"/><div>Vue 单文件组件 <small>.vue · 背景内嵌，即拿即用</small></div></button><button @click="jsonDownload"><FileJson :size="15"/><div>可编辑配置 <small>.json · 随时导入继续设计</small></div></button></div></div></div></header>
 <div class="studio-workspace">
  <aside class="studio-library"><div class="studio-library-tabs"><button :class="{active:sidebar==='presets'}" @click="sidebar='presets'"><Image :size="15"/>背景素材</button><button :class="{active:sidebar==='layers'}" @click="sidebar='layers'"><Layers :size="15"/>图层 <small>{{config.lines.length+1}}</small></button></div>
   <template v-if="sidebar==='presets'"><div class="studio-library-intro"><span class="studio-eyebrow">CURATED COLLECTION</span><h2>从一张好背景开始<span>{{String(presets.length).padStart(2,'0')}}</span></h2><p>为大屏而生，光轨已经为你对齐。</p></div><div class="studio-search"><Search :size="14"/><input v-model="query" aria-label="搜索背景" placeholder="搜索风格、场景…"/><span>⌕</span></div><div class="studio-categories"><button v-for="c in ['全部','新作','城市','园区','农业','工业','通用']" :class="{active:category===c}" @click="category=c">{{c}}</button></div><div class="studio-preset-list"><button v-for="p in filtered" :key="p.id" class="studio-preset" :class="{active:config.presetId===p.id}" @click="applyPreset(p)"><div class="preset-art"><svg viewBox="0 0 1600 300" preserveAspectRatio="none"><rect width="1600" height="300" fill="#06121e"/><svg width="1600" height="300" :viewBox="`${p.background.crop.x} ${p.background.crop.y} ${p.background.crop.w} ${p.background.crop.h}`" preserveAspectRatio="none"><image :href="p.thumbnail||p.background.url" :width="p.background.width" :height="p.background.height" :style="{filter:p.background.filter||'none'}"/></svg><text x="800" y="155" text-anchor="middle" fill="#dfebf4" font-size="55" letter-spacing="18">{{p.title.slice(0,6)}}</text></svg><span v-if="p.fresh" class="preset-new">NEW</span><span class="preset-check" v-if="config.presetId===p.id"><Check :size="11"/></span></div><div class="preset-info"><div><strong>{{p.name}}</strong><span>{{p.en}}</span></div><small><i :style="{background:p.color}"></i>{{p.tag}}</small></div></button><div v-if="!filtered.length" class="studio-empty"><Search :size="22"/><p>没有找到匹配背景</p><button @click="query='';category='全部'">查看全部预设</button></div></div><button class="studio-upload" :disabled="uploadBusy" @click="fileInput.click()"><Upload :size="17"/><div><strong>{{uploadBusy?'正在读取图片…':'上传自己的背景'}}</strong><span>PNG / JPG / WebP · 最大 3 MB</span></div><Plus :size="14"/></button><input ref="fileInput" type="file" accept="image/png,image/jpeg,image/webp" hidden @change="uploadBackground"/></template>
   <template v-else><div class="studio-library-intro"><span class="studio-eyebrow">COMPOSITION</span><h2>每一层，都可掌控</h2><p>选择光轨，在画布上拖动节点。</p></div><div class="studio-layer-list"><button class="studio-layer" :class="{active:selectedId==='title'}" @click="focusTitle"><Type :size="17"/><span><strong>标题与副标题</strong><small>{{config.title}}</small></span></button><div v-for="l in [...config.lines].reverse()" :key="l.id" class="studio-layer" :class="{active:selectedId===l.id,hidden:!l.visible}"><button class="layer-select" @click="selectedId=l.id;setTool('select')"><component :is="l.kind==='curve'?Spline:PenLine" :size="17"/><span><strong>{{l.name}}</strong><small>{{l.points.length}} 个节点 {{l.mirror?'· 镜像':''}}</small></span><i :style="{background:l.color}"></i></button><button class="layer-eye" :aria-label="l.visible?'隐藏'+l.name:'显示'+l.name" @click="toggleVisible(l)"><component :is="l.visible?Eye:EyeOff" :size="14"/></button></div><div class="studio-layer studio-bg-layer" @click="selectedId=null"><Image :size="17"/><span><strong>背景素材</strong><small>{{activePreset?.name||'自定义图片'}}</small></span></div></div><button class="studio-add-layer" @click="setTool('line');message('在画布上点击添加节点，Enter 完成绘制')"><Plus :size="15"/>绘制新光轨</button></template>
   <div class="studio-library-bottom"><span><i></i>所有设计在你的浏览器中完成</span><button @click="shortcutsOpen=true"><Keyboard :size="14"/>快捷键</button></div>
  </aside>
  <main class="studio-main"><div class="studio-document-bar"><div><span class="studio-document-dot"></span><strong>{{activePreset?.name||'自定义 Header'}}</strong><span class="studio-document-type">HEADER</span></div><div class="studio-history"><button :disabled="!canUndo&&!draft.length" title="撤销 ⌘Z" aria-label="撤销" @click="undoAction"><Undo2 :size="16"/></button><button :disabled="!canRedo" title="重做 ⌘⇧Z" aria-label="重做" @click="redo"><Redo2 :size="16"/></button><i></i><button title="导入配置" aria-label="导入配置" @click="jsonInput.click()"><Upload :size="14"/><span>导入</span></button><button title="查看组件代码" aria-label="查看组件代码" @click="codeOpen=true"><Code2 :size="16"/><span>代码</span></button></div></div>
   <div class="studio-canvas-area"><div class="studio-toolbar" role="toolbar" aria-label="绘图与视图工具"><div class="tool-segment"><button :class="{active:tool==='select'}" title="选择 / 移动 V" aria-label="选择工具" @click="setTool('select')"><MousePointer2 :size="17"/></button><button :class="{active:tool==='line'}" title="绘制折线 P" aria-label="绘制折线" @click="setTool('line')"><PenLine :size="18"/></button><button :class="{active:tool==='curve'}" title="绘制曲线 B" aria-label="绘制曲线" @click="setTool('curve')"><Spline :size="19"/></button></div><i></i><button :class="{active:showGrid}" title="显示网格 G" aria-label="显示网格" :aria-pressed="showGrid" @click="showGrid=!showGrid"><Grid2X2 :size="16"/></button><button :class="{active:snap}" title="吸附到 10px 网格" aria-label="网格吸附" :aria-pressed="snap" @click="snap=!snap"><Magnet :size="16"/></button><button :class="{active:showGuides}" title="显示参考线与节点" aria-label="显示参考线" :aria-pressed="showGuides" @click="showGuides=!showGuides"><ScanLine :size="16"/></button><i></i><button :class="{active:mirrorDraw}" title="新线条左右镜像" aria-label="绘制镜像" :aria-pressed="mirrorDraw" @click="mirrorDraw=!mirrorDraw"><MoveHorizontal :size="17"/></button><i></i><button class="tool-play" :title="playing?'暂停动画 Space':'播放动画 Space'" :aria-label="playing?'暂停动画':'播放动画'" @click="playing=!playing"><component :is="playing?Pause:Play" :size="15"/><span>{{playing?'播放中':'已暂停'}}</span><span class="playing-dot" :class="{paused:!playing}"></span></button></div>
    <div class="studio-canvas-heading"><div><span class="studio-eyebrow">YOUR NEXT GREAT HEADER</span><h1>让灵感，沿着光的轨迹发生<span>。</span></h1></div><p>自由绘制 · 实时呈现 · 即刻交付</p></div>
    <div class="studio-board-scroller"><div class="studio-board-wrap" :style="{width:(zoom*100)+'%'}"><div class="studio-board-meta"><span><i></i>HEADER CANVAS <b>{{config.width}} × {{config.height}}</b></span><span>{{Math.round(zoom*100)}}% <small>适应画布</small></span></div><div ref="stage" class="studio-board" :class="{drawing:tool!=='select'}" :style="{aspectRatio:`1600 / ${config.height}`}" @pointermove="move" @pointerup="endDrag" @pointercancel="endDrag" @pointerleave="pointer=null;hoverPoint=null">
     <HeaderRenderer :config="config" :playing="playing" :resolved-paths="resolvedPaths"/>
     <svg class="studio-interaction" :viewBox="`0 0 1600 ${config.height}`" preserveAspectRatio="none" @pointerdown="canvasDown" @dblclick.prevent="finish">
      <defs><pattern id="studio-grid" width="40" height="40" patternUnits="userSpaceOnUse"><path d="M40 0H0V40" fill="none" stroke="#7facc0" stroke-width=".4" opacity=".3"/></pattern></defs><rect v-if="showGrid" width="1600" :height="config.height" fill="url(#studio-grid)" pointer-events="none"/>
      <g v-if="showGuides" stroke="#73a3b2" stroke-width=".65" stroke-dasharray="5 7" opacity=".45" pointer-events="none"><path :d="`M800 0V${config.height}`"/><path :d="`M0 ${config.titleY}H1600`"/></g>
      <template v-if="tool==='select'"><rect :x="config.titleX-Math.max(210,config.title.length*(config.fontSize+config.letterSpacing)*.48)" :y="config.titleY-config.fontSize" :width="Math.max(420,config.title.length*(config.fontSize+config.letterSpacing)*.96)" :height="config.fontSize+46" fill="transparent" class="studio-title-hit" :stroke="selectedId==='title'?'#70ddca':'none'" stroke-dasharray="4 4" stroke-width=".8" @pointerdown="startTitle"/>
       <g v-for="{line:l,paths} in resolvedPaths" :key="l.id"><path v-for="(path,j) in paths" :key="j" :d="path.d" fill="none" stroke="transparent" stroke-width="18" class="studio-line-hit" @pointerdown.stop="selectLine(l.id)"/></g>
       <template v-if="selected&&selected.visible&&showGuides"><g v-for="(points,j) in selected.mirror?[selected.points,mirrored(selected.points)]:[selected.points]" :key="j"><path :d="selectedPaths[j]?.d" fill="none" stroke="#b1fff0" stroke-width=".8" stroke-dasharray="4 5" opacity=".85" pointer-events="none"/><circle v-for="(p,i) in points" :key="i" :cx="p.x" :cy="p.y" r="5" fill="#0b2833" stroke="#9af1da" stroke-width="1.4" class="studio-node" @pointerdown="startNode($event,i,j===1)" @dblclick.stop.prevent="deleteNode(i)"><title>节点 {{i+1}} · {{Math.round(p.x)}}, {{Math.round(p.y)}} · 双击删除</title></circle></g></template>
      </template>
      <g v-if="draft.length" fill="none" stroke="#9af1da" stroke-width="1.7" pointer-events="none"><path :d="draftD"/><path v-if="mirrorDraw" :d="pathData(mirrored([...draft,...(hoverPoint?[hoverPoint]:[])]),tool==='curve'?'curve':'line')" opacity=".55"/><circle v-for="(p,i) in draft" :key="i" :cx="p.x" :cy="p.y" r="4" fill="#08232d"/></g>
     </svg></div><div class="studio-board-bottom"><span><component :is="tool==='select'?MousePointer2:PenLine" :size="12"/>{{tool==='select'?(showGuides?'选择光轨可拖动节点 · 拖动标题调整位置':'点击光轨进入节点编辑 · 拖动标题调整位置'):'点击添加节点 · Shift 水平/垂直 · Enter 或双击完成'}}</span><span v-if="pointer" class="studio-coordinates">X {{Math.round(pointer.x).toString().padStart(4,'0')}} <i>/</i> Y {{Math.round(pointer.y).toString().padStart(3,'0')}}</span><button v-if="draft.length" class="finish-drawing" @click="finish"><Check :size="12"/>完成绘制</button></div></div></div>
    <div class="studio-canvas-note"><span class="canvas-note-line"></span><span>设计可见，灵感可用</span><span class="canvas-note-line"></span></div>
    <div class="studio-workflow-cards"><article><div><Image :size="17"/></div><span>01<small>精选背景</small></span><p>从精心调校的风格开始</p></article><article><div><Spline :size="18"/></div><span>02<small>勾勒光轨</small></span><p>让每条线与设计自然契合</p></article><article><div><Code2 :size="18"/></div><span>03<small>交付代码</small></span><p>独立 Vue 组件，直接使用</p></article></div>
    <div class="studio-canvas-footer"><div><span class="canvas-view-label">视图</span><button :class="{active:referenceMode==='header'}" @click="referenceMode='header'">Header</button><button :class="{active:referenceMode==='screen'}" @click="referenceMode='screen';openPreview()">大屏预览 <ArrowUpRight :size="11"/></button></div><div><button aria-label="缩小画布" :disabled="zoom<=.75" @click="zoom=Math.max(.75,zoom-.25)"><Minus :size="14"/></button><button class="zoom-fit" @click="zoom=1">{{Math.round(zoom*100)}}%</button><button aria-label="放大画布" :disabled="zoom>=2" @click="zoom=Math.min(2,zoom+.25)"><Plus :size="14"/></button><i></i><button aria-label="适应画布" title="适应画布" @click="zoom=1"><Focus :size="15"/></button></div></div>
   </div>
   <footer class="studio-statusbar"><span><i></i>Vue 3 / SVG Animation <b>交点自动裁剪{{trimmedCount?' · '+trimmedCount+' 段已收口':''}}</b></span><span>{{config.lines.length}} 条光轨 · {{pointCount}} 个节点<button @click="shortcutsOpen=true"><Keyboard :size="13"/>快捷键</button></span></footer>
  </main>
  <aside class="studio-inspector"><div class="inspector-heading"><SlidersHorizontal :size="16"/><h2>设计参数</h2><span>实时生效</span></div><div class="studio-inspector-scroll">
   <div class="inspector-selection"><span class="studio-eyebrow">{{selected?'PATH PROPERTIES':selectedId==='title'?'TYPOGRAPHY':'CANVAS SETTINGS'}}</span><div><component :is="selected?(selected.kind==='curve'?Spline:PenLine):selectedId==='title'?Type:PanelTop" :size="18"/><input v-if="selected" v-model="selected.name" aria-label="光轨名称" maxlength="40" @change="record"/><strong v-else>{{selectedId==='title'?'标题与副标题':'画布与背景'}}</strong><span v-if="selected" class="selection-badge">{{selected.mirror?'镜像':'单线'}}</span></div></div>
   <template v-if="selected"><section class="inspector-section"><div class="inspector-section-title"><h3>光轨样式</h3><button aria-label="复制当前光轨" title="复制 ⌘D" @click="duplicateSelected"><Copy :size="13"/></button></div><div class="property-field effect-library"><label>效果预设 <span>{{lineEffects.length}} 款</span></label><div class="effect-categories" role="group" aria-label="效果分类"><button v-for="c in ['全部','流光','光点','幻影','脉冲']" :key="c" :class="{active:effectCategory===c}" :aria-pressed="effectCategory===c" @click="effectCategory=c">{{c}}</button></div><div class="effect-picker"><button v-for="e in availableEffects" :key="e.id" :class="{active:selected.effect===e.id}" :title="e.description" :aria-pressed="selected.effect===e.id" @click="chooseEffect(e)"><EffectSwatch :effect="e"/><span>{{e.name}}<Check v-if="selected.effect===e.id" :size="10"/></span></button></div><p class="effect-description"><i></i>{{selectedEffect?.description}}</p></div><div class="property-color"><label>光轨颜色</label><div><input type="color" v-model="selected.color" aria-label="光轨颜色" @change="record"/><input :value="selected.color.toUpperCase()" aria-label="光轨颜色 HEX" maxlength="7" @change="/^#[0-9a-f]{6}$/i.test($event.target.value)?(selected.color=$event.target.value,record()):($event.target.value=selected.color)"/></div></div><StudioRange v-model="selected.width" label="线条宽度" :min=".3" :max="8" :step=".1" unit="px" @change="record"/><StudioRange v-model="selected.glow" label="发光强度" :min="0" :max="20" unit="px" @change="record"/><StudioRange v-model="selected.opacity" label="不透明度" :min=".1" :max="1" :step=".05" @change="record"/></section><section class="inspector-section"><div class="inspector-section-title"><h3>运动节奏</h3><span class="subtle-live"><i></i>SYNC</span></div><StudioRange v-model="selected.duration" label="单次时长" :min="1" :max="20" :step=".5" unit="s" @change="record"/><StudioRange v-if="tailEffects.includes(selected.effect)" v-model="selected.tail" label="光尾长度" :min="15" :max="400" unit="‰" @change="record"/><div class="property-field"><label>运动方向</label><div class="segmented-control"><button :class="{active:selected.direction==='forward'}" @click="selected.direction='forward';record()">起点 → 终点</button><button :class="{active:selected.direction==='reverse'}" @click="selected.direction='reverse';record()">终点 → 起点</button></div></div><label class="studio-toggle-row"><span><strong>左右镜像</strong><small>共享运动节奏，始终同步</small></span><input type="checkbox" v-model="selected.mirror" @change="record"/><i></i></label></section><section class="inspector-section"><div class="inspector-section-title"><h3>几何与节点</h3><span>{{selected.points.length}} POINTS</span></div><div class="segmented-control"><button :class="{active:selected.kind==='line'}" @click="selected.kind='line';record()"><PenLine :size="13"/>折线</button><button :class="{active:selected.kind==='curve'}" @click="selected.kind='curve';record()"><Spline :size="13"/>平滑曲线</button></div><p v-if="selectedPaths.some(p=>p.trimmed)" class="studio-trim-hint"><CheckCheck :size="13"/>交点后的多余部分已裁剪，原始节点可继续编辑。</p><button class="add-point-button" @click="addNode"><Plus :size="13"/>增加节点</button><div class="inspector-node-list"><div v-for="(p,i) in selected.points" :key="i"><span>{{String(i+1).padStart(2,'0')}}</span><label>X<input type="number" :value="Math.round(p.x)" min="0" max="1600" :aria-label="'节点'+(i+1)+'横坐标'" @change="p.x=Math.max(0,Math.min(1600,Number($event.target.value)||0));record()"/></label><label>Y<input type="number" :value="Math.round(p.y)" min="0" :max="config.height" :aria-label="'节点'+(i+1)+'纵坐标'" @change="p.y=Math.max(0,Math.min(config.height,Number($event.target.value)||0));record()"/></label><button :aria-label="'删除节点'+(i+1)" @click="deleteNode(i)"><X :size="11"/></button></div></div></section><button class="inspector-delete" @click="remove"><Trash2 :size="13"/>删除光轨 <span>⌫</span></button></template>
   <template v-else><section class="inspector-section"><div class="inspector-section-title"><h3>文字内容</h3><Type :size="13"/></div><label class="studio-text-field">主标题<input v-model="config.title" maxlength="80" @change="record"/></label><label class="studio-text-field">英文副标题<textarea v-model="config.subtitle" rows="2" maxlength="160" @change="record"></textarea></label><div class="property-color"><label>标题颜色</label><div><input type="color" v-model="config.titleColor" aria-label="标题颜色" @change="record"/><span>{{config.titleColor.toUpperCase()}}</span></div></div><StudioRange v-model="config.fontSize" label="标题字号" :min="16" :max="80" unit="px" @change="record"/><StudioRange v-model="config.letterSpacing" label="文字间距" :min="0" :max="24" unit="px" @change="record"/><div class="property-two"><label>X<input type="number" v-model.number="config.titleX" min="0" max="1600" aria-label="标题横坐标" @change="config.titleX=Math.max(0,Math.min(1600,config.titleX||0));record()"/></label><label>Y<input type="number" v-model.number="config.titleY" min="0" :max="config.height" aria-label="标题纵坐标" @change="config.titleY=Math.max(0,Math.min(config.height,config.titleY||0));record()"/></label></div><StudioRange v-model="config.subtitleSize" label="副标题字号" :min="6" :max="24" unit="px" @change="record"/></section><section class="inspector-section"><div class="inspector-section-title"><h3>画布与背景</h3><button title="恢复背景裁切" aria-label="恢复背景裁切" @click="resetBackground"><RotateCcw :size="13"/></button></div><StudioRange v-model="config.height" label="画布高度" :min="120" :max="600" :step="10" unit="px" @change="record"/><StudioRange v-model="config.background.opacity" label="背景可见度" :min="0" :max="1" :step=".05" @change="record"/><StudioRange v-model="config.background.crop.y" label="垂直裁切位置" :min="0" :max="config.background.height" unit="px" @change="record"/><StudioRange v-model="config.background.crop.h" label="裁切高度" :min="20" :max="config.background.height" unit="px" @change="record"/><div class="property-color"><label>画布底色</label><div><input type="color" v-model="config.bgColor" aria-label="画布底色" @change="record"/><span>{{config.bgColor.toUpperCase()}}</span></div></div></section></template>
   <div class="inspector-tip"><Info :size="14"/><p>{{selected?(showGuides?'拖动画布中的节点精调轨迹。双击节点删除，⌘D 快速复制。':'点击画布光轨或开启参考线可编辑节点。选择效果预设后仍可继续精调。'):'拖动画布中的标题调整位置。所有修改自动保存到当前浏览器。'}}</p></div></div><div class="studio-inspector-bottom"><button @click="selectedId=selectedId==='title'?null:'title'"><component :is="selectedId==='title'?PanelTop:Type" :size="14"/>{{selectedId==='title'?'画布设置':'编辑标题与背景'}}<ChevronRight :size="13"/></button></div></aside>
 </div>
 <input ref="jsonInput" type="file" accept="application/json,.json" hidden @change="importJson"/>
 <Transition name="studio-toast"><div v-if="toast" class="studio-toast-message" role="status"><CheckCheck :size="16"/>{{toast}}</div></Transition>
 <div v-if="preview" class="studio-modal-backdrop studio-preview-backdrop" @click.self="closePreview"><section class="studio-preview-dialog" role="dialog" aria-modal="true" aria-label="Header 实时预览"><div class="studio-modal-heading"><div><span class="preview-live-dot"></span><strong>实时预览</strong><span>像交付时一样，审视每一个细节。</span></div><div><select v-model.number="previewWidth" aria-label="预览宽度"><option :value="1920">1920 · 大屏</option><option :value="1600">1600 · 桌面</option><option :value="1280">1280 · 笔记本</option><option :value="768">768 · 平板</option></select><button @click="playing=!playing" :aria-label="playing?'暂停预览':'播放预览'"><component :is="playing?Pause:Play" :size="16"/></button><button @click="closePreview" aria-label="关闭预览"><X :size="19"/></button></div></div><div class="preview-context" :style="{maxWidth:previewWidth+'px'}"><div :style="{aspectRatio:`1600 / ${config.height}`}" class="preview-header"><HeaderRenderer :config="config" :playing="playing" :resolved-paths="resolvedPaths"/></div><div class="preview-dashboard-context"><div class="preview-kpi" v-for="(n,i) in ['98.6','36,892','99.2','128']"><span>{{['综合运行指数','在线感知设备','服务可用率','今日处置事件'][i]}}</span><strong>{{n}}</strong><small>↑ {{[.8,2.6,.12,3.2][i]}}%</small></div><div class="preview-context-grid"><div class="preview-context-panel"><span>运行态势</span><div v-for="i in 5" :style="{width:(32+i*12)+'%'}"></div></div><div class="preview-context-center"><span class="context-orbit"></span><small>HEADER IN CONTEXT</small><p>你的设计，已经准备就绪</p></div><div class="preview-context-panel"><span>设备状态</span><div v-for="i in 5" :style="{width:(94-i*10)+'%'}"></div></div></div></div></div><div class="preview-caption"><span>预览不会改变原始画布尺寸 · 所见即所得</span><button class="studio-btn primary" @click="exportFile()"><Download :size="14"/>导出这个设计</button></div></section></div>
 <div v-if="codeOpen" class="studio-modal-backdrop" @click.self="codeOpen=false"><section class="studio-code-dialog" role="dialog" aria-modal="true" aria-label="组件代码"><div class="studio-modal-heading"><div><Code2 :size="18"/><strong>你的设计，已是代码</strong></div><button @click="codeOpen=false" aria-label="关闭代码"><X :size="19"/></button></div><div class="studio-code-tabs"><div><button :class="{active:codeTab==='vue'}" @click="codeTab='vue'">DashboardHeader.vue</button><button :class="{active:codeTab==='json'}" @click="codeTab='json'">header.config.json</button></div><button @click="copyCode"><component :is="copied?Check:Copy" :size="13"/>{{copied?'已复制':'复制代码'}}</button></div><pre tabindex="0"><code>{{code}}</code></pre><div class="studio-code-footer"><span>Vue 3.5+ · 原生 SVG 动画 · 响应式 · 支持暂停</span><button class="studio-btn primary" @click="exportFile()"><Download :size="14"/>下载完整组件包</button></div></section></div>
 <div v-if="shortcutsOpen" class="studio-modal-backdrop" @click.self="shortcutsOpen=false"><section class="studio-shortcuts-dialog" role="dialog" aria-modal="true" aria-label="快捷键"><div class="studio-modal-heading"><div><Keyboard :size="18"/><strong>让创作更顺手</strong></div><button @click="shortcutsOpen=false" aria-label="关闭快捷键"><X :size="18"/></button></div><div class="shortcut-list"><div v-for="[name,key] in [['选择与移动','V'],['绘制折线','P'],['绘制平滑曲线','B'],['完成绘制','Enter / 双击'],['水平或垂直连线','Shift + 点击'],['撤销 / 重做','⌘ Z / ⌘ ⇧ Z'],['复制光轨','⌘ D'],['删除光轨或最后节点','⌫'],['播放 / 暂停','Space'],['显示 / 隐藏网格','G'],['关闭窗口或取消绘制','Esc']]"><span>{{name}}</span><kbd>{{key}}</kbd></div></div><p>Windows / Linux 使用 Ctrl 替代 ⌘。</p></section></div>
</div></template>
